corrected_code:
@login_required
def publish_wagtail_page_view(request, page_id):
    page = get_object_or_404(Page, id=page_id).specific
    page_perms = page.permissions_for_user(request.user)
    if not page_perms.can_publish():
        raise PermissionDenied("You do not have permission to publish this page.")
    revision = page.save_revision()
    revision.publish()
    return JsonResponse({'status': 'published', 'page_id': page.id, 'title': page.title})
